      "aciklama": "Maya, 1-2 yaşlarında kısır bir kız. İnsan canlısı, sevecen ve bol bol sevilmeye bayılan bir çocuk. Tanıştığı herkese sevgiyle yaklaşıyor, çocuklarla çok iyi anlaşıyor. Evde oldukça uyumlu, yalnız kalabiliyor. Tuvalet eğitimi tam. Evde oyun oynamayı çok sevse de uzun uzun dinlenmekten de çok keyif alıyor. Dışarıda ise mutlu, enerjik ve keyifli. Tasmayla çekiştirmeden, uyumlu bir şekilde yürüyor. Diğer köpeklerle arası iyi. Kedilere de oyun oynamak için yaklaşıyor, kovalama eğilimi yok. Sevilmekten, oyun oynamaktan ve insanıyla vakit geçirmekten büyük mutluluk duyan Maya’nın ömürlük yuvasını arıyoruz.",
