      "renkEn": null,
      "konumEn": null,
      "saglikNotuEn": null,
      "karakterEn": [
        "affectionate"
      ],
      "aciklamaEn": "These two souls were abandoned by the family they considered home under the pretext of 'moving abroad'. Now they are trying to understand what happened and why they suddenly found themselves here. They are so scared that they barely eat and stand side by side without leaving each other for even a moment. Right now, their only refuge is each other 😞 They urgently need a safe, loving home so they can leave this fear behind. To adopt, you can fill out the form on our kurtaranev.org/sahiplendirme page. 🙏",
