      "kedilerleUyum": null,
      "karakter": [],
      "aciklama": "Kömür, 9 yaşında, erkek ve kısır. Hayatın ona hiç de kolay davranmadığı ama tüm zorluklara rağmen hayata tutunmayı başaran güzel çocuklardan biri. 🖤 Araba çarpması sonrası gençlik hastalığıyla da mücadele eden Kömür, uzun ve zorlu tedavi süreçlerinin ardından sağlığına kavuştu. Yıllardır Kurtaran Ev’de güvenle yaşamını sürdürüyor. ✨ Ama onun yalnızca güvende değil, kendisine ait bir yuvası ve ailesi olması gerekiyor. 🙏🏻 Bugüne kadar Kömür’e ömürlük yuvasını açacak kişi ne yazık ki çıkmadı. 😞 Kömür’e evinde ya da bahçesinde bir yer açacak, ona ömrünün geri kalanında “sen artık bizimlesin” diyec…",
      "cinsEn": null,
      "renkEn": null,
      "konumEn": null,
      "saglikNotuEn": "Having also battled distemper after being hit by a car, Kömür regained his health following long and challenging treatment processes.",
      "karakterEn": [],
      "aciklamaEn": "Kömür is 9 years old, male, and neutered. He is one of those beautiful souls whom life has not treated easily at all, but who managed to hold on to life despite all hardships. 🖤 Having also fought distemper after being hit by a car, Kömür regained his health following long and difficult treatment processes. He has been living safely at Kurtaran Ev for years. ✨ But he needs not just to be safe, but to have a home and a family of his own. 🙏🏻 Unfortunately, no one has come forward to give Kömür a forever home until now. 😞 Someone who will make a place for Kömür in their home or garden, telling him for the rest of his life \"you are with us now\"...",
