      "karakter": [
        "sevecen",
        "eğitimli"
      ],
      "aciklama": "Gönüllü geçici yuvamızdaki Rita, 5-6 yaşlarında, kısır dişi, çok neşeli, müthiş insan aşığı, süper uyumlu bir kız. Deneyimsiz yuva adayları çok uygun, son derece sosyal, gittiğiniz her yere uyumla size eşlik edebilecek bir çocuk. Kediyle beraber yaşamaya alışık. Çocuklarla çok iyi geçiniyor. Sevilmekten hiç sıkılmayan, çok sevgi dolu, temas seven bir çocuk. Tuvalet eğitimi tam, apartman hayatına uyumlu. Arabaya alışık, uzun yol seyahatleri de seviyor. Tasmada çok uyumlu yürüyor. 🐾 Sahiplenemiyorsanız, ilanı paylaşabilirsiniz 🙏",
      "cinsEn": null,
      "renkEn": null,
      "konumEn": "Volunteer foster home",
      "saglikNotuEn": null,
      "karakterEn": [
        "affectionate",
        "trained"
      ],
      "aciklamaEn": "Rita, currently in our volunteer foster home, is a 5-6 year old spayed female who is very joyful, a huge people lover, and a super adaptable girl. She is very suitable for first-time adopters, highly social, and a dog who can harmoniously accompany you wherever you go. She is used to living with cats. She gets along very well with children. She never tires of being petted, is extremely affectionate, and loves physical contact. She is fully house-trained and suitable for apartment life. She is accustomed to cars and also loves long road trips. She walks very nicely on a leash. 🐾 If you cannot adopt, please share this post 🙏",
