      "aciklama": "Bizim tatlı Susam’ımız geçici yuvaya çıktı. Susam 2 yaşlarında, kısır dişi, küçük-orta ırk arası bir kız. Tuvalet eğitimi var. Çocuklarla çok iyi anlaşıyor. Bütün gün sevseniz sıkılmayacak, müthiş tatlı ve yumuşacık huylu bir sevgi pıtırcığı. Gerektiğinde evde yalnız kalabiliyor. Başka köpeklerle sorunsuz; kediyle de beraber yaşayabileceğini düşünüyoruz. Çok hızlı bağ kurabilen, çok pozitif ve neşeli bir kız. Arabaya alışık. Her ortama ayak uydurabilen, sizinle ofise, kafeye, her yere birlikte gelebilecek sosyallikte bir çocuk. Ömürlük yuvasını arıyoruz.",
