      "karakter": [
        "çekingen",
        "sevecen",
        "meraklı",
        "uyumlu"
      ],
      "aciklama": "Yıllardır bizimle olan Uzay’ımıza geçici yuva bulabildik ve onun sayesinde Uzay ilerleme kaydetmeye başladı bile. Evdeki diğer köpeği kendine mentor belledi, sürekli onu taklit ettiği için ev ve şehir hayatına adapte olmaya başladı. İnsanların ani hareketlerinden hala çekiniyor olsa da, tanıdığı insanların onu sevmesinden çok hoşlanıyor, hatta karnını açıp okşatmayı bile seviyor artık. Tasmayla yürümeye alıştı. Dışarıda oldukça meraklı ve heyecanlı olmasına rağmen, tasmayı çekiştirmeden, gayet uyumlu yürüyor. Dışarıda vakit geçirmeyi, koşmayı çok seviyor. Minyon boyutlu olduğu için, gerektiğinde kucağa almak da mümkün olabiliyor. Kedi kaçarsa kovalıyor ama köpeğe alışık bir kediyle beraber yaşamaya alışabileceğini düşünüyoruz. Uzay’ın açılması, güvende hissetmesi için sabır ve emek gösterebilecek, ömürlük yuvasını arıyoruz.",
      "cinsEn": "Tricolor Setter",
      "renkEn": null,
      "konumEn": "Foster home",
      "saglikNotuEn": null,
      "karakterEn": [
        "shy",
        "affectionate",
        "curious",
        "adaptable"
      ],
      "aciklamaEn": "We were fortunate to find a foster home for Uzay, who has been with us for years, and thanks to it, Uzay has already started making progress. Uzay chose the other dog in the house as a mentor and began adapting to home and city life by constantly mimicking them. Although still shy around sudden movements, Uzay really enjoys affection from familiar people and even loves exposing their belly for rubs now. Uzay is used to walking on a leash, walking very harmoniously without pulling despite being curious and excited outdoors. Uzay loves spending time outside and running. Due to a compact size, picking Uzay up when needed is also possible. Uzay chases cats if they run, but we believe adaptation to living with a cat used to dogs is possible. We are looking for a forever home that will show patience and effort for Uzay to open up and feel safe.",
      "fotograflar": [
        "assets/img/animals/ig-DW1LE-HjKmQ-0.jpg",
        "assets/img/animals/ig-DW1LE-HjKmQ-1.jpg",
        "assets/img/animals/ig-DW1LE-HjKmQ-2.jpg"
      ],
