      "yasMetni": null,
      "yasMetniEn": null,
      "yasGrubu": null,
      "arama": "uzay tricolor setter geçici yuva yıllardır bizimle olan uzay’ımıza geçici yuva bulabildik ve onun sayesinde uzay ilerleme kaydetmeye başladı bile. evdeki diğer köpeği kendine mentor belledi, sürekli onu taklit ettiği için ev ve şehir hayatına adapte olmaya başladı. i̇nsanların ani hareketlerinden hala çekiniyor olsa da, tanıdığı insanların onu sevmesinden çok hoşlanıyor, hatta karnını açıp okşatmayı bile seviyor artık. tasmayla yürümeye alıştı. dışarıda oldukça meraklı ve heyecanlı olmasına rağmen, tasmayı çekiştirmeden, gayet uyumlu yürüyor. dışarıda vakit geçirmeyi, koşmayı çok seviyor. minyon boyutlu olduğu için, gerektiğinde kucağa almak da mümkün olabiliyor. kedi kaçarsa kovalıyor ama köpeğe alışık bir kediyle beraber yaşamaya alışabileceğini düşünüyoruz. uzay’ın açılması, güvende hissetmesi için sabır ve emek gösterebilecek, ömürlük yuvasını arıyoruz. çekingen sevecen meraklı uyumlu",
      "aramaEn": "uzay tricolor setter foster home we were fortunate to find a foster home for uzay, who has been with us for years, and thanks to it, uzay has already started making progress. uzay chose the other dog in the house as a mentor and began adapting to home and city life by constantly mimicking them. although still shy around sudden movements, uzay really enjoys affection from familiar people and even loves exposing their belly for rubs now. uzay is used to walking on a leash, walking very harmoniously without pulling despite being curious and excited outdoors. uzay loves spending time outside and running. due to a compact size, picking uzay up when needed is also possible. uzay chases cats if they run, but we believe adaptation to living with a cat used to dogs is possible. we are looking for a forever home that will show patience and effort for uzay to open up and feel safe. shy affectionate curious adaptable"
