      "ozelBakim": true,
      "saglikNotu": "Aldığı bir darbe sonucu omurgası kırılmış ve sinirlerinde hasar meydana gelmiştir. Hareketlerinde ciddi kısıtlama yoktur, yürüyüp koşabilir fakat sinir hasarı nedeniyle bazen çiş kaçırabilmektedir.",
      "cocuklaUyum": null,
      "kopeklerleUyum": null,
      "kedilerleUyum": null,
      "karakter": [
        "sakin",
        "sevecen"
      ],
      "aciklama": "Chia 4 yaşlarında, kısır dişi, çok yumuşak huylu ve naif bir kız. Başına ne geldi bilmiyoruz ama aldığı bir darbe sonucu omurgası kırılmış ve bundan dolayı da sinirlerde bir hasar meydana gelmiş. Hareketlerinde ciddi bir kısıt yok, yürüyebiliyor, hatta koşabiliyor ama maalesef sinirlerde oluşan hasar dolayısıyla bazen çiş kaçırabiliyor. Tuvalet kazalarını tolere edemeyecek biri olursa, ev içinde köpek külodu giydirmek çözüm olabilir ama ona bu özeni gösterecek birini bulma ümidimiz çok az. Normal şartlarda küçük ırkları bahçeye yuvalandırmıyor olsak da, bütün hayatını toplu alanda geçirmesindense, en azından Bodrum, Antalya gibi hiç olmazsa İstanbul’dan daha sıcak bir iklimde, ona bahçesinde bakmak isteyen biri olursa, değerlendirmek istiyoruz.",
      "cinsEn": null,
      "renkEn": null,
      "konumEn": null,
      "saglikNotuEn": "She suffered a broken spine due to a blow, resulting in nerve damage. Her mobility is not severely restricted—she can walk and run—but due to nerve damage, she occasionally experiences urinary incontinence.",
      "karakterEn": [
        "calm",
        "affectionate"
      ],
      "aciklamaEn": "Chia is around 4 years old, a spayed female with a very gentle and sweet nature. We don't know what happened to her, but she suffered a broken spine from a blow, which caused nerve damage. She has no severe mobility restriction, can walk and even run, but unfortunately she sometimes leaks urine due to the nerve damage. If someone cannot tolerate accidents, using dog diapers indoors can be a solution, though our hope of finding someone willing to provide this care is small. Although we normally do not adopt small breeds out to garden homes, we are open to considering someone with a garden in a warmer climate like Bodrum or Antalya, rather than having her spend her entire life in a group shelter environment.",
